-- Temple ID 1: วัดพระเชตุพนวิมลมังคลาราม (วัดโพธิ์)
ON CONFLICT (id) DO UPDATE SET item_name = EXCLUDED.item_name, price = EXCLUDED.price, is_active = EXCLUDED.is_active;

ON CONFLICT (id) DO UPDATE SET event_name = EXCLUDED.event_name, event_date = EXCLUDED.event_date, event_time = EXCLUDED.event_time;

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content;

