INSERT INTO events (id, temple_id, event_name, description, event_date, event_time) VALUES
  (148, 13, 'งานทำบุญตักบาตรและเวียนเทียน วันสำคัญทางพระพุทธศาสนา', 'ขอเชิญพุทธศาสนิกชนร่วมทำบุญตักบาตรข้าวสารอาหารแห้ง ฟังพระธรรมเทศนา และเวียนเทียนรอบพระอุโบสถ', '2026-11-15', '07:00:00'),
  (149, 13, 'งานประเพณีทอดกฐินสามัคคีประจำปี (วัดสระเกศราชวรมหาวิหาร)', 'ขอเชิญร่วมเป็นเจ้าภาพทอดกฐินสามัคคี เพื่อสมทบทุนบูรณปฏิสังขรณ์เสนาสนะและถาวรวัตถุภายในวัด', '2026-11-28', '09:30:00'),
  (150, 13, 'พิธีสวดมนต์ข้ามปี เจริญจิตภาวนา เสริมสิริมงคลชีวิต', 'ร่วมส่งท้ายปีเก่าต้อนรับปีใหม่ ด้วยการสวดมนต์ข้ามปี รับฟังธรรมโอวาท และรับน้ำพระพุทธมนต์เพื่อความเป็นสิริมงคล', '2026-12-31', '22:00:00'),
  (151, 13, 'งานประจำปี นมัสการปิดทองพระพุทธรูปศักดิ์สิทธิ์', 'งานสมโภชปิดทองไหว้พระ ขอพรสิ่งศักดิ์สิทธิ์ประจำวัด พร้อมการออกร้านจำหน่ายสินค้าชุมชนและการแสดงมหรสพสมโภช', '2027-02-20', '08:00:00')
INSERT INTO news (id, temple_id, title, content) VALUES
  (136, 13, 'ขอเชิญร่วมทำบุญและร่วมกิจกรรมทางพระพุทธศาสนา ณ วัดสระเกศราชวรมหาวิหาร', 'ทางวัดขอเชิญชวนพุทธศาสนิกชนและสาธุชนทุกท่าน ร่วมทำบุญ ตักบาตร รักษาศีล และเจริญจิตตภาวนา ณ บริเวณพระวิหารและพระอุโบสถ สามารถเดินทางมาร่วมบุญได้ทุกวัน'),
  (137, 13, 'ประกาศกำหนดการและเวลาเปิด-ปิดการเข้าสักการะ', 'เพื่อความสะดวกและความเป็นระเบียบเรียบร้อย ทางวัดเปิดให้พุทธศาสนิกชนเข้าสักการะพระประธานและเยี่ยมชมโบราณสถาน ตั้งแต่เวลา 07.00 น. ถึง 18.00 น. ของทุกวัน'),
  (138, 13, 'โครงการบูรณปฏิสังขรณ์เสนาสนะและถาวรวัตถุวัด', 'ทางวัดกำลังดำเนินการบูรณปฏิสังขรณ์หลังคาพระอุโบสถและศาลาการเปรียญ ขอเชิญผู้มีจิตศรัทธาร่วมทำบุญตามกำลังศรัทธา ผ่านระบบ E-Donation ของทางวัดได้ตลอด 24 ชั่วโมง')
INSERT INTO bookable_items (id, temple_id, item_name, item_type, description, price, total_qty, is_active) VALUES
  (165, 14, 'ศาลา 1 เมรุ/พิธีสวดอภิธรรม (วัดกัลยาณมิตรวรมหาวิหาร)', 'pavilion_funeral', 'ศาลาปรับอากาศสำหรับประกอบพิธีสวดอภิธรรมและฌาปนกิจ พร้อมอุปกรณ์อำนวยความสะดวกครบครัน', 2000, 1, 'yes'),
  (166, 14, 'ศาลาการเปรียญ ทำบุญเลี้ยงพระ/พิธีมงคล', 'pavilion_merit', 'ศาลาทรงไทยกว้างขวาง เหมาะสำหรับจัดงานทำบุญครบรอบ งานมงคลสมรส หรืองานบุญอุทิศส่วนกุศล', 1200, 1, 'yes'),
  (167, 14, 'นิมนต์พระสงฆ์ 9 รูป ประกอบพิธีมงคล', 'monk', 'นิมนต์พระสงฆ์เจริญพระพุทธมนต์ ฉันภัตตาหารเพล/เช้า ทำบุญบ้าน และพิธีมงคลต่างๆ', 0, 1, 'yes'),
  (168, 14, 'ชุดโต๊ะหมู่บูชา เต็นท์พิธี และเก้าอี้ 100 ตัว', 'equipment', 'ยืมอุปกรณ์สำหรับจัดงานพิธี ชุดโต๊ะหมู่บูชา อาสนะสงฆ์ เต็นท์ผ้าใบ และเก้าอี้พลาสติกพร้อมผ้าคลุม', 400, 5, 'yes'),
  (169, 14, 'ล็อคจำหน่ายสินค้า งานประจำปี/งานวัด (โซน A)', 'fair_stall', 'พื้นที่ขนาด 3x3 เมตร สำหรับตั้งร้านจำหน่ายอาหาร ขนม สินค้าชุมชน และของที่ระลึกในงานวัด', 600, 25, 'yes')
