  (246, 49, 'โครงการบูรณปฏิสังขรณ์เสนาสนะและถาวรวัตถุวัด', 'ทางวัดกำลังดำเนินการบูรณปฏิสังขรณ์หลังคาพระอุโบสถและศาลาการเปรียญ ขอเชิญผู้มีจิตศรัทธาร่วมทำบุญตามกำลังศรัทธา ผ่านระบบ E-Donation ของทางวัดได้ตลอด 24 ชั่วโมง')
INSERT INTO bookable_items (id, temple_id, item_name, item_type, description, price, total_qty, is_active) VALUES
  (345, 50, 'ศาลา 1 เมรุ/พิธีสวดอภิธรรม (วัดบึง)', 'pavilion_funeral', 'ศาลาปรับอากาศสำหรับประกอบพิธีสวดอภิธรรมและฌาปนกิจ พร้อมอุปกรณ์อำนวยความสะดวกครบครัน', 2000, 1, 'yes'),
  (346, 50, 'ศาลาการเปรียญ ทำบุญเลี้ยงพระ/พิธีมงคล', 'pavilion_merit', 'ศาลาทรงไทยกว้างขวาง เหมาะสำหรับจัดงานทำบุญครบรอบ งานมงคลสมรส หรืองานบุญอุทิศส่วนกุศล', 1200, 1, 'yes'),
  (347, 50, 'นิมนต์พระสงฆ์ 9 รูป ประกอบพิธีมงคล', 'monk', 'นิมนต์พระสงฆ์เจริญพระพุทธมนต์ ฉันภัตตาหารเพล/เช้า ทำบุญบ้าน และพิธีมงคลต่างๆ', 0, 1, 'yes'),
  (348, 50, 'ชุดโต๊ะหมู่บูชา เต็นท์พิธี และเก้าอี้ 100 ตัว', 'equipment', 'ยืมอุปกรณ์สำหรับจัดงานพิธี ชุดโต๊ะหมู่บูชา อาสนะสงฆ์ เต็นท์ผ้าใบ และเก้าอี้พลาสติกพร้อมผ้าคลุม', 400, 5, 'yes'),
  (349, 50, 'ล็อคจำหน่ายสินค้า งานประจำปี/งานวัด (โซน A)', 'fair_stall', 'พื้นที่ขนาด 3x3 เมตร สำหรับตั้งร้านจำหน่ายอาหาร ขนม สินค้าชุมชน และของที่ระลึกในงานวัด', 600, 25, 'yes')
INSERT INTO events (id, temple_id, event_name, description, event_date, event_time) VALUES
  (296, 50, 'งานทำบุญตักบาตรและเวียนเทียน วันสำคัญทางพระพุทธศาสนา', 'ขอเชิญพุทธศาสนิกชนร่วมทำบุญตักบาตรข้าวสารอาหารแห้ง ฟังพระธรรมเทศนา และเวียนเทียนรอบพระอุโบสถ', '2026-11-15', '07:00:00'),
  (297, 50, 'งานประเพณีทอดกฐินสามัคคีประจำปี (วัดบึง)', 'ขอเชิญร่วมเป็นเจ้าภาพทอดกฐินสามัคคี เพื่อสมทบทุนบูรณปฏิสังขรณ์เสนาสนะและถาวรวัตถุภายในวัด', '2026-11-28', '09:30:00'),
  (298, 50, 'พิธีสวดมนต์ข้ามปี เจริญจิตภาวนา เสริมสิริมงคลชีวิต', 'ร่วมส่งท้ายปีเก่าต้อนรับปีใหม่ ด้วยการสวดมนต์ข้ามปี รับฟังธรรมโอวาท และรับน้ำพระพุทธมนต์เพื่อความเป็นสิริมงคล', '2026-12-31', '22:00:00'),
  (299, 50, 'งานประจำปี นมัสการปิดทองพระพุทธรูปศักดิ์สิทธิ์', 'งานสมโภชปิดทองไหว้พระ ขอพรสิ่งศักดิ์สิทธิ์ประจำวัด พร้อมการออกร้านจำหน่ายสินค้าชุมชนและการแสดงมหรสพสมโภช', '2027-02-20', '08:00:00')
